DEG = math.pi / 180

# ======================================================================
#   TIME, COORDINATES, THE SUN, THE MOON AND THE PLANETS
# ======================================================================
def norm360(a):
    return a % 360.0


def jd_ut(y, m, d, h):
    if m <= 2:
        y -= 1
        m += 12
    A = y // 100
    B = 2 - A + A // 4
    return math.floor(365.25 * (y + 4716)) + math.floor(30.6001 * (m + 1)) + d + B - 1524.5 + h / 24


def gmst_deg(J):
    t = (J - 2451545) / 36525
    return norm360(280.46061837 + 360.98564736629 * (J - 2451545) + 0.000387933 * t * t)


def vec(ra, dec):
    return (math.cos(dec * DEG) * math.cos(ra * DEG), math.cos(dec * DEG) * math.sin(ra * DEG), math.sin(dec * DEG))


def radec(v):
    n = math.sqrt(v[0] ** 2 + v[1] ** 2 + v[2] ** 2)
    return norm360(math.atan2(v[1], v[0]) / DEG), math.asin(max(-1, min(1, v[2] / n))) / DEG


def mv(M, v):
    return (M[0][0] * v[0] + M[0][1] * v[1] + M[0][2] * v[2], M[1][0] * v[0] + M[1][1] * v[1] + M[1][2] * v[2],
            M[2][0] * v[0] + M[2][1] * v[1] + M[2][2] * v[2])


def mvT(M, v):
    return (M[0][0] * v[0] + M[1][0] * v[1] + M[2][0] * v[2], M[0][1] * v[0] + M[1][1] * v[1] + M[2][1] * v[2],
            M[0][2] * v[0] + M[1][2] * v[1] + M[2][2] * v[2])


def unit(v):
    n = math.sqrt(v[0] ** 2 + v[1] ** 2 + v[2] ** 2)
    return (v[0] / n, v[1] / n, v[2] / n)


def dot(a, b):
    return a[0] * b[0] + a[1] * b[1] + a[2] * b[2]


def precession(J):
    t = (J - 2451545) / 36525
    a = DEG / 3600
    z = (2306.2181 * t + 1.09468 * t * t) * a
    ze = (2306.2181 * t + 0.30188 * t * t) * a
    th = (2004.3109 * t - 0.42665 * t * t) * a
    cz, sz, ce, se, ct, st = math.cos(z), math.sin(z), math.cos(ze), math.sin(ze), math.cos(th), math.sin(th)
    return ((cz * ct * ce - sz * se, -cz * ct * se - sz * ce, -cz * st),
            (sz * ct * ce + cz * se, -sz * ct * se + cz * ce, -sz * st),
            (st * ce, -st * se, ct))


EPS = 23.4393 * DEG


def ecl2eq(v):
    return (v[0], v[1] * math.cos(EPS) - v[2] * math.sin(EPS), v[1] * math.sin(EPS) + v[2] * math.cos(EPS))


# JPL approximate Keplerian elements (1800-2050): a, e, I, L, long.peri, long.node and their rates
ELEM = {
    "mercury": (0.38709927, 0.00000037, 0.20563593, 0.00001906, 7.00497902, -0.00594749, 252.25032350, 149472.67411175, 77.45779628, 0.16047689, 48.33076593, -0.12534081),
    "venus": (0.72333566, 0.00000390, 0.00677672, -0.00004107, 3.39467605, -0.00078890, 181.97909950, 58517.81538729, 131.60246718, 0.00268329, 76.67984255, -0.27769418),
    "earth": (1.00000261, 0.00000562, 0.01671123, -0.00004392, -0.00001531, -0.01294668, 100.46457166, 35999.37244981, 102.93768193, 0.32327364, 0, 0),
    "mars": (1.52371034, 0.00001847, 0.09339410, 0.00007882, 1.84969142, -0.00813131, -4.55343205, 19140.30268499, -23.94362959, 0.44441088, 49.55953891, -0.29257343),
    "jupiter": (5.20288700, -0.00011607, 0.04838624, -0.00013253, 1.30439695, -0.00183714, 34.39644051, 3034.74612775, 14.72847983, 0.21252668, 100.47390909, 0.20469106),
    "saturn": (9.53667594, -0.00125060, 0.05386179, -0.00050991, 2.48599187, 0.00193609, 49.95424423, 1222.49362201, 92.59887831, -0.41897216, 113.66242448, -0.28867794)}


def helio(p, J):
    t = (J - 2451545) / 36525
    E0 = ELEM[p]
    el = [E0[2 * i] + E0[2 * i + 1] * t for i in range(6)]
    a, e, I, L, w, O = el[0], el[1], el[2] * DEG, el[3], el[4], el[5]
    om, M = (w - O) * DEG, norm360(L - w) * DEG
    E = M + e * math.sin(M)
    for _ in range(8):
        E -= (E - e * math.sin(E) - M) / (1 - e * math.cos(E))
    xp, yp, Or = a * (math.cos(E) - e), a * math.sqrt(1 - e * e) * math.sin(E), O * DEG
    co, so, cO, sO, cI, sI = math.cos(om), math.sin(om), math.cos(Or), math.sin(Or), math.cos(I), math.sin(I)
    return ((co * cO - so * sO * cI) * xp + (-so * cO - co * sO * cI) * yp,
            (co * sO + so * cO * cI) * xp + (-so * sO + co * cO * cI) * yp,
            so * sI * xp + co * sI * yp)


def planet_geo(p, J):
    """geocentric equatorial J2000 vector (au), corrected for light time"""
    e = helio("earth", J)
    Jt, g = J, None
    for _ in range(2):
        h = helio(p, Jt)
        g = (h[0] - e[0], h[1] - e[1], h[2] - e[2])
        Jt = J - math.sqrt(dot(g, g)) * 0.0057755
    return ecl2eq(g)


def sun_geo(J):
    e = helio("earth", J)
    return ecl2eq((-e[0], -e[1], -e[2]))


def moon_geo(J):
    """the Moon, low precision (Meeus ch. 47, main terms): unit vector, J2000"""
    t = (J - 2451545) / 36525
    Lp = norm360(218.3164477 + 481267.88123421 * t)
    D = norm360(297.8501921 + 445267.1114034 * t) * DEG
    M = norm360(357.5291092 + 35999.0502909 * t) * DEG
    Mp = norm360(134.9633964 + 477198.8675055 * t) * DEG
    F = norm360(93.2720950 + 483202.0175233 * t) * DEG
    lon = (Lp + 6.288774 * math.sin(Mp) + 1.274027 * math.sin(2 * D - Mp) + 0.658314 * math.sin(2 * D) + 0.213618 * math.sin(2 * Mp)
           - 0.185116 * math.sin(M) - 0.114332 * math.sin(2 * F) + 0.058793 * math.sin(2 * D - 2 * Mp) + 0.057066 * math.sin(2 * D - M - Mp)
           + 0.053322 * math.sin(2 * D + Mp) + 0.045758 * math.sin(2 * D - M))
    lat = (5.128122 * math.sin(F) + 0.280602 * math.sin(Mp + F) + 0.277693 * math.sin(Mp - F) + 0.173237 * math.sin(2 * D - F)
           + 0.055413 * math.sin(2 * D - Mp + F) + 0.046271 * math.sin(2 * D - Mp - F))
    return ecl2eq(vec(lon - 1.396971 * t, lat))


# ======================================================================
#   THE OBSERVER AND THE NIGHT
# ======================================================================
OBS_LAT, OBS_LON, OBS_TZ = 46.755, 17.245, 2
SKY = {"J0": jd_ut(2019, 8, 4, 21 + 42 / 60), "t": 0.0, "k": 0.24, "haze": False, "twilight": 0.0}


def jd_now():
    return SKY["J0"] + SKY["t"] / 86400


def lst_deg(J):
    return norm360(gmst_deg(J) + OBS_LON)


_PM = {"M": None, "J": 0}


def pm(J):
    if _PM["M"] is None or abs(J - _PM["J"]) > 1:
        _PM["M"], _PM["J"] = precession(J), J
    return _PM["M"]


def eq_date(v, J):
    ra, dec = radec(mv(pm(J), v))
    return norm360(lst_deg(J) - ra), dec, ra


def hadec2hor(ha, dec):
    H, d, p = ha * DEG, dec * DEG, OBS_LAT * DEG
    alt = math.asin(max(-1, min(1, math.sin(p) * math.sin(d) + math.cos(p) * math.cos(d) * math.cos(H))))
    az = math.atan2(-math.cos(d) * math.sin(H), math.sin(d) * math.cos(p) - math.cos(d) * math.sin(p) * math.cos(H))
    return alt / DEG, norm360(az / DEG)


def hor2hadec(alt, az):
    a, A, p = alt * DEG, az * DEG, OBS_LAT * DEG
    d = math.asin(max(-1, min(1, math.sin(p) * math.sin(a) + math.cos(p) * math.cos(a) * math.cos(A))))
    H = math.atan2(-math.sin(A) * math.cos(a), math.sin(a) * math.cos(p) - math.cos(a) * math.sin(p) * math.cos(A))
    return norm360(H / DEG), d / DEG


def date_radec_to_j2000(ra, dec, J):
    return mvT(pm(J), vec(ra, dec))


def hor_matrix(J):
    """J2000 -> horizon (E, N, Up)"""
    P = precession(J)
    th, p = lst_deg(J) * DEG, OBS_LAT * DEG
    c, s = math.cos(th), math.sin(th)
    Rz = ((c, s, 0), (-s, c, 0), (0, 0, 1))
    A = ((0, 1, 0), (-math.sin(p), 0, math.cos(p)), (math.cos(p), 0, math.sin(p)))

    def mm(X, Y):
        return tuple(tuple(X[i][0] * Y[0][j] + X[i][1] * Y[1][j] + X[i][2] * Y[2][j] for j in range(3)) for i in range(3))
    return mm(A, mm(Rz, P))


def altaz(h):
    return math.asin(max(-1, min(1, h[2]))) / DEG, norm360(math.atan2(h[0], h[1]) / DEG)


def hvec(alt, az):
    return (math.sin(az * DEG) * math.cos(alt * DEG), math.cos(az * DEG) * math.cos(alt * DEG), math.sin(alt * DEG))


def refr(a):
    return 1.02 / math.tan((a + 10.3 / (a + 5.11)) * DEG) / 60 if a > -2 else 0


def airmass(a):
    s = math.sin(max(1, a) * DEG)
    return 1 / (s + 0.025 * math.exp(-11 * s))


def haze_k(alt):                      # the low haze over the lake and the marsh
    return WXS["haze"] * (0.12 + 2.4 * max(0, min(1, (27 - alt) / 7)))


def extinct(alt):
    return (SKY["k"] + haze_k(alt)) * airmass(alt)


# ---- the night sky as an observer sees it -------------------------------------------------
#  Sky brightness = the natural night sky (airglow, brighter toward the horizon) + the light domes of
#  Keszthely to the north, Heviz to the north-west and the far shore, + twilight; in units of a natural
#  dark zenith (21.6 mag/arcsec^2).  The eye's limiting magnitude follows from it (Schaefer 1990), stars
#  lose light along the air mass, and every star is a point whose brightness - not its size - tells its
#  magnitude; only the brightest carry the eye's glare and show their colour.
SITE = {"lp_zen": 0.85, "domes": ((4, 2.6, 13), (32, 0.9, 10), (302, 0.8, 9), (140, 0.18, 6))}
SUN = [-30.0, 0.0]


def sky_lum(alt, az):
    a = max(0.5, alt)
    X, sz = airmass(a), math.sin((90 - a) * DEG)
    nat = (0.45 + 0.55 / math.sqrt(1 - 0.96 * sz * sz)) * 10 ** (-0.4 * 0.16 * (X - 1)) + 0.2 * (1 - math.exp(-0.3 * (X - 1)))
    lp = SITE["lp_zen"] * (0.7 + 0.3 * X ** 0.6)
    for A, S, Hs in SITE["domes"]:
        d = abs(((az - A + 540) % 360) - 180)
        lp += S * math.exp(-a / Hs) * math.exp(-((d / 40) ** 2))
    ch, cm = cloud_at(a, az)                                      # haze and clouds, lit by the town
    lp = lp * (1 + 0.8 * WXS["haze"]) + (0.5 * ch + 0.8 * cm) * (0.25 + 1.2 * lp)
    nat *= (1 + 0.15 * WXS["haze"]) * (1 - 0.25 * ch - 0.7 * cm)
    ds = abs(((az - SUN[1] + 540) % 360) - 180)
    tw = 60 * ((SUN[0] + 18) / 6) ** 3 * (0.35 + 0.65 * math.exp(-((ds / 75) ** 2)) * math.exp(-a / 30)) if SUN[0] > -18 else 0.0
    return nat, lp, tw


def sqm_of(L):
    return 21.6 - 2.5 * math.log10(sum(L))


def nelm_of(q):                       # Schaefer: naked-eye limit for a sky of q mag/arcsec^2
    return 7.93 - 5 * math.log10(10 ** (4.316 - q / 5) + 1)


def adapt():                          # the eye adapts to the dark over the first minutes outside
    return min(1.0, 0.6 + SKY["t"] / 300)


OBSERVER = 0.3                        # Schaefer's limit is an experienced observer's; a student sees about 0.3 mag less


def lim_eye(alt, az=180.0):
    return nelm_of(sqm_of(sky_lum(alt, az))) - 1.0 * (1 - adapt()) - OBSERVER


def twinkle(i, X, amp):               # stars twinkle, more near the horizon
    A, t = min(0.55, amp * X ** 1.5), SKY["t"]
    return 2.5 * math.log10(max(0.25, 1 + A * math.sin(t * (9 + i % 7) + i * 1.7) * math.sin(t * (5.3 + (i % 5) * 0.6) + i * 0.37)))


# ======================================================================
#   SATURN, ITS RINGS AND MOONS
# ======================================================================
SAT_POLE = vec(40.589, 83.537)


def saturn_geom(J):
    g = planet_geo("saturn", J)
    dist = math.sqrt(dot(g, g))
    u = unit(g)
    n = SAT_POLE
    B = math.asin(-dot(u, n)) / DEG
    ra, dec = radec(u)
    N = (-math.sin(dec * DEG) * math.cos(ra * DEG), -math.sin(dec * DEG) * math.sin(ra * DEG), math.cos(dec * DEG))
    E = (-math.sin(ra * DEG), math.cos(ra * DEG), 0)
    P = math.atan2(dot(n, E), dot(n, N)) / DEG
    return {"dist": dist, "B": B, "P": P, "req": 60268 / (dist * 1.495978707e8) / DEG * 3600, "u": u, "N": N, "E": E}


MOONS = [("Titan", 1221870, 15.945421, 0.666, 8.4), ("Rhea", 527108, 4.518212, 1.3, 9.7),
         ("Dione", 377396, 2.736915, 4.1, 10.4), ("Tethys", 294619, 1.887802, 2.6, 10.2)]


def moon_offsets(J):
    """offsets (arcsec east, arcsec north) of the moons on circular orbits in Saturn's equator"""
    G, n = saturn_geom(J), SAT_POLE
    x = (1 - n[0] * n[0], -n[0] * n[1], -n[0] * n[2])
    x = unit(x)
    y = (n[1] * x[2] - n[2] * x[1], n[2] * x[0] - n[0] * x[2], n[0] * x[1] - n[1] * x[0])
    s = 1 / (G["dist"] * 1.495978707e8) / DEG * 3600
    out = []
    for name, a, P, th0, mg in MOONS:
        th = th0 + 2 * math.pi * (J - 2458700) / P
        r = tuple(a * (math.cos(th) * x[i] + math.sin(th) * y[i]) for i in range(3))
        out.append({"n": name, "de": dot(r, G["E"]) * s, "dn": dot(r, G["N"]) * s, "mag": mg, "behind": dot(r, G["u"]) > 0})
    return out


