# fainter field stars where the catalogue stops (outside the deep fields), fixed per half-degree cell
MGAL = ((-0.0548755604, -0.8734370902, -0.4838350155), (0.4941094279, -0.4448296300, 0.7469822445), (-0.8676661490, -0.1980763734, 0.4559837762))
DEEP = [vec(283.3963, 33.0292), vec(307.5537, 46.5579), vec(281.0846, 39.67), vec(297.6958, 8.8683), unit(planet_geo("saturn", jd_ut(2019, 8, 5, 0)))]
PCELL, MLIM, CDEEP = {}, 12.6, math.cos(2.25 * DEG)


def n_cum(m, b):
    return 10 ** (0.42 * m - 3.05) * (1 + 2.2 * math.exp(-abs(b) / 12))


def cell_stars(i, j):
    key = i * 1000 + j
    if key in PCELL:
        return PCELL[key]
    R = random.Random(key)
    ra0, dec0 = i * 0.5, -90 + j * 0.5
    b = math.asin(mv(MGAL, vec(ra0 + 0.25, dec0 + 0.25))[2]) / DEG
    route = 262 <= ra0 < 322 and -36 <= dec0 < 62
    mmin = 9.3 if route else 6.0
    area = 0.25 * math.cos((dec0 + 0.25) * DEG)
    N = area * (n_cum(MLIM, b) - n_cum(mmin, b))
    lo, hi = 10 ** (0.42 * mmin), 10 ** (0.42 * MLIM)
    out = []
    for _ in range(int(N + R.random())):
        v = vec(ra0 + 0.5 * R.random(), dec0 + 0.5 * R.random())
        m = math.log10(lo + R.random() * (hi - lo)) / 0.42
        bv = 0.3 + 1.1 * R.random() ** 1.5
        if any(dot(d, v) > CDEEP for d in DEEP):
            continue
        out.append((v, m, bv))
    PCELL[key] = out
    return out


# comparison stars around AF Cyg, about 0.3 mag apart
def _comps():
    L = sorted([(CX[i], CM[i]) for i in near(307.5537, 46.5579, 1.3) if 6.3 < CM[i] < 9.7], key=lambda s: s[1])
    out = []
    for s in L:
        if not out or s[1] - out[-1][1] >= 0.28:
            out.append(s)
    return out[:9]


