SCOPE_F, SCOPE_AFOV = 750, 52


def focus_zero():
    return (0.9 if EP["fl"] == 10 else 0) + (2.2 if EP["barlow"] else 0)


def magnif():
    return SCOPE_F * (2 if EP["barlow"] else 1) / EP["fl"]


def tfov():
    return SCOPE_AFOV / magnif()


def centre(dha=0.0, ddec=0.0):
    return norm360(lst_deg(jd_now()) - (MOUNT["ha"] + dha)), max(-89.9, min(89.9, MOUNT["dec"] + ddec))


CAND = {"c": None, "list": []}


def candidates(ra, dec):
    """stars within 6 deg of the field centre, kept as of-date (ra, dec) for the night"""
    c = CAND["c"]
    if c and abs(c[0] - ra) * math.cos(dec * DEG) < 1 and abs(c[1] - dec) < 1:
        return CAND["list"]
    J = jd_now()
    v = date_radec_to_j2000(ra, dec, J)
    P = pm(J)
    cc, cp = math.cos(6 * DEG), math.cos(4.8 * DEG)
    out = []
    for i in range(len(CX)):
        if CM[i] < 50 and dot(CX[i], v) > cc:
            out.append(radec(mv(P, CX[i])) + (CM[i], CBV[i]))
    for e in EXTRA:
        if dot(e[0], v) > cc:
            out.append(radec(mv(P, e[0])) + (e[1], e[2]))
    r2, d2 = radec(v)
    j0, j1 = max(0, int((d2 - 4.8 + 90) // 0.5)), min(359, int((d2 + 4.8 + 90) // 0.5))
    w = 4.8 / max(0.08, math.cos(min(85, abs(d2) + 4.8) * DEG))
    for j in range(j0, j1 + 1):
        for i in range(int((r2 - w) // 0.5), int((r2 + w) // 0.5) + 1):
            for st in cell_stars(i % 720, j):
                if dot(st[0], v) > cp:
                    out.append(radec(mv(P, st[0])) + (st[1], st[2]))
    CAND["c"], CAND["list"] = (ra, dec), out
    return out


def std_coord(ra, dec, ra0, dec0):
    a, d, d0 = (ra - ra0) * DEG, dec * DEG, dec0 * DEG
    cc = math.sin(d0) * math.sin(d) + math.cos(d0) * math.cos(d) * math.cos(a)
    if cc < 0.5:
        return None
    return (math.cos(d) * math.sin(a) / cc / DEG, (math.cos(d0) * math.sin(d) - math.sin(d0) * math.cos(d) * math.cos(a)) / cc / DEG)


